      async findMatchingChatResponse(message) {
        const lowerMessage = message.toLowerCase().trim();
        const responses = await this.getActiveChatAutomatedResponses();
        console.log("\u{1F916} Bot matching attempt:", {
          message: lowerMessage,
          totalResponses: responses.length,
          triggers: responses.map((r) => r.trigger)
        });
        const calculateSimilarity = (str1, str2) => {
          const normalize2 = (s) => s.replace(/[^\w\s]/g, "").replace(/\s+/g, " ").trim();
          const norm1 = normalize2(str1);
          const norm2 = normalize2(str2);
          if (norm1 === norm2) return 1;
          const words1 = norm1.split(/\s+/).filter((w) => w.length >= 3);
          const words2 = norm2.split(/\s+/).filter((w) => w.length >= 3);
          if (words1.length === 0 || words2.length === 0) return 0;
          const matchingWords = words1.filter(
            (w1) => words2.some((w2) => w1 === w2)
          ).length;
          if (matchingWords === 0) return 0;
          const totalWords = Math.max(words1.length, words2.length);
          const ratio = matchingWords / totalWords;
          if (matchingWords >= 2 && ratio >= 0.75) {
            return Math.min(ratio + 0.2, 0.95);
          }
          const triggerTokens = norm2.split(/\s+/).filter((w) => w.length >= 3);
          if (triggerTokens.length === 1 && matchingWords === 1) {
            return Math.max(ratio, 0.8);
          }
          return ratio;
        };
        let bestMatch;
        let highestScore = 0;
        for (const response of responses) {
          const trigger = response.trigger.toLowerCase();
          const score = calculateSimilarity(lowerMessage, trigger);
          const messageWords = lowerMessage.replace(/[^\w\s]/g, "").trim().split(/\s+/).filter((w) => w.length >= 3);
          let threshold = 0.75;
          if (messageWords.length === 1) {
            threshold = 0.95;
          } else if (messageWords.length === 2) {
            threshold = 0.7;
          }
          console.log(`\u{1F50D} Checking trigger "${trigger}" against "${lowerMessage}": score=${score.toFixed(2)}, threshold=${threshold}`);
          if (score > highestScore && score >= threshold) {
            highestScore = score;
            bestMatch = response;
          }
        }
        if (bestMatch) {
          console.log("\u2705 Found matching response:", {
            trigger: bestMatch.trigger,
            category: bestMatch.category,
            score: highestScore.toFixed(2),
            hasResponseEn: !!bestMatch.responseEn
          });
          return bestMatch;
        }
        console.log("\u274C No matching response found for:", lowerMessage);
        return void 0;
      }
