async function formatAmountForUser(userId2, usdAmountStr) {
  try {
    const user = await storage.getUser(userId2);
    const currency2 = user?.preferredCurrency;
    if (!currency2 || currency2 === "USD") {
      return `$${parseFloat(usdAmountStr).toFixed(2)}`;
    }
    const sym = CURRENCY_SYMBOLS[currency2] || `${currency2} `;
    const usd = parseFloat(usdAmountStr);
    if (currency2 === "HTG") {
      return `${sym}${(usd * HTG_FIXED_RATE).toFixed(2)}`;
    }
    const rate = await storage.getExchangeRate(currency2);
    if (rate?.rateToUSD) {
      return `${sym}${(usd * parseFloat(rate.rateToUSD)).toFixed(2)}`;
    }
    return `$${usd.toFixed(2)}`;
  } catch {
    return `$${parseFloat(usdAmountStr).toFixed(2)}`;
  }
}
