    cardPayments: account.capabilities?.card_payments,
    liveEnabled,
    walletCreditEnabled: liveEnabled,
    airtimeDeliveryEnabled: liveEnabled,
    reason: !expectedAccountId ? "STRIPE_EXPECTED_ACCOUNT_NOT_CONFIGURED" : !accountMatches ? "STRIPE_ACCOUNT_MISMATCH" : keys.mode === "test" ? "TEST_MODE_NO_REAL_PAYMENTS" : !cardsReady ? "STRIPE_CARD_PAYMENTS_INACTIVE" : "LIVE_READY"
