init_storage();
var round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
async function calculateDynamicFee(serviceName, amount4, fallbackFlatRate = 5) {
  try {
    const rules = await storage.getServiceFeeRules(serviceName);
    const matchedRule = rules.find((r) => {
      const min = parseFloat(r.minAmount || "0");
      const max = r.maxAmount ? parseFloat(r.maxAmount) : Infinity;
      return amount4 >= min && amount4 < max;
    });
    const catchAll = !matchedRule ? rules.find((r) => {
      const min = parseFloat(r.minAmount || "0");
      return r.maxAmount === null && amount4 >= min;
    }) : null;
    const rule = matchedRule || catchAll;
    if (rule) {
      const value = parseFloat(rule.feeValue || "0");
      const fee2 = rule.feeType === "fixed" ? round2(value) : round2(amount4 * value / 100);
      return { fee: fee2, feeType: rule.feeType, feeValue: value, tiered: true };
    }
  } catch (e) {
    console.error("calculateDynamicFee: rule lookup failed, using fallback:", e);
  }
  return {
    fee: round2(amount4 * fallbackFlatRate / 100),
    feeType: "percentage",
    feeValue: fallbackFlatRate,
    tiered: false
  };
}

