function walletGiftCardLegacyActionConflict(order) {
  const metadata = order?.metadata;
  if (metadata?.paymentMethod !== "wallet" || metadata?.walletDebited !== true) return null;
  const alreadyRefunded = metadata.autoRefunded === true || metadata.walletRefunded === true;
  return {
    success: false,
    error: alreadyRefunded ? "WALLET_GIFTCARD_ALREADY_REFUNDED" : "WALLET_GIFTCARD_RECONCILIATION_REQUIRED",
    message: alreadyRefunded ? "This wallet gift card was already refunded atomically. Do not refund or deliver it again. A new purchase requires a new payment." : "Action blocked: this wallet gift card requires provider reconciliation, not a legacy retry, completion, failure or refund. Support must verify the exact custom identifier with the provider, recover any existing delivery, and use the atomic wallet settlement flow only after an authoritative result. Not found or timeout is not proof of failure.",
    transactionId: order.id,
    customIdentifier: order.customIdentifier,
    provider: metadata.provider,
    status: order.status,
    alreadyRefunded
  };
}
function blockLegacyWalletGiftCardAction(order, res) {
  const conflict = walletGiftCardLegacyActionConflict(order);
  if (!conflict) return false;
  res.status(409).json(conflict);
  return true;
}

