// server/cashPickPaymentGate.ts
init_paypal();
init_threeDSecureGate();
async function verifyCashPickPaid(tx) {
  const paypalOrderId2 = (tx.paymentReference || "").split("|")[0]?.trim();
  const isPayPalFunded = tx?.paymentMethod === "paypal" || !!paypalOrderId2;
  if (!isPayPalFunded) {
    return { ok: true };
  }
  if (!paypalOrderId2) {
    console.error("\u{1F6A8} CASH PICK PAYMENT GATE: PayPal transfer has no order reference \u2014 cannot verify payment.");
    return {
      ok: false,
      errorCode: "PAYMENT_UNVERIFIED",
      confirmedUnpaid: true,
      message: "Cannot pay out: this PayPal transfer has no payment reference, so the payment cannot be verified."
    };
  }
  try {
    const getResult = await ordersController.getOrder({ id: paypalOrderId2 });
    const rawOd = getResult.body;
    const od = typeof rawOd === "string" ? JSON.parse(rawOd) : rawOd;
    const cap = od?.purchase_units?.[0]?.payments?.captures?.[0];
    const capStatus = cap?.status || od?.status;
    const capAmount = parseFloat(cap?.amount?.value || "0");
    const expectedAmount = parseFloat(tx.amountUSD || "0");
    if (capStatus !== "COMPLETED" || capAmount + 0.02 < expectedAmount) {
      console.error(
        `\u{1F6A8} CASH PICK PAYMENT GATE: PayPal not paid \u2014 order ${paypalOrderId2}, status=${capStatus}, captured=$${capAmount}, expected>=$${expectedAmount}`
      );
      return {
        ok: false,
        errorCode: "PAYMENT_NOT_CAPTURED",
        confirmedUnpaid: true,
        message: `Cannot pay out: PayPal payment was not captured (status: ${capStatus || "UNKNOWN"}, captured: $${capAmount.toFixed(2)}, required: $${expectedAmount.toFixed(2)}). This transfer has been cancelled.`
      };
    }
    const cardGate = await enforceThreeDSecureLiability(paypalOrderId2, od, {
      userId: tx.userId || void 0
    });
    if (cardGate.blocked) {
      return {
        ok: false,
        errorCode: "PAYMENT_UNVERIFIED",
        confirmedUnpaid: false,
        message: `Cannot pay out: PayPal card verification failed (AVS=${cardGate.avsCode || "missing"}, 3DS=${cardGate.liabilityShift || "missing"}).`
      };
    }
    console.log(`\u2705 CASH PICK PAYMENT GATE: PayPal payment verified for order ${paypalOrderId2} (captured $${capAmount})`);
    return { ok: true };
  } catch (err) {
    console.error(`\u{1F6AB} CASH PICK PAYMENT GATE: PayPal verification error for order ${paypalOrderId2} (failing closed):`, err?.message);
    return {
      ok: false,
      errorCode: "PAYMENT_VERIFY_FAILED",
      confirmedUnpaid: false,
      message: "Cannot pay out: unable to verify this PayPal payment right now. Please try again shortly."
    };
  }
}

