async function refundCreditInTx(tx, userId2, amount4, description, relatedTransactionId) {
  return moveDepositWalletInTx(tx, userId2, amount4, "refund", description, relatedTransactionId);
}
async function refundPayPalToSource(orderId2, expectedAmount, userId2, idempotencyKey) {
  const id2 = (orderId2 || "").trim().split("|")[0].trim();
  if (!id2) return { ok: false, indeterminate: false, reason: "no PayPal order reference" };
  try {
    const accessToken = await getPayPalAccessToken();
    const resp = await fetch(`https://api-m.paypal.com/v2/checkout/orders/${id2}`, {
      headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }
    });
    if (!resp.ok) return { ok: false, indeterminate: false, reason: "could not read PayPal order" };
    const od = await resp.json();
    const pu = od?.purchase_units?.[0];
    const cap = pu?.payments?.captures?.[0];
    const captureId = (cap?.id || "").toString();
    const capStatus = cap?.status;
    const capAmount = parseFloat(cap?.amount?.value || "0");
    const capCurrency = (cap?.amount?.currency_code || "").toUpperCase();
    if (!captureId) return { ok: false, indeterminate: false, reason: "no capture on order" };
    if (capStatus === "REFUNDED") return { ok: true, alreadyRefunded: true };
    if (capStatus !== "COMPLETED" && capStatus !== "PARTIALLY_REFUNDED") {
      return { ok: false, indeterminate: false, reason: `capture status ${capStatus || "?"}` };
    }
    if (capCurrency && capCurrency !== "USD") {
      return { ok: false, indeterminate: false, reason: `currency ${capCurrency} != USD` };
    }
    if (capAmount + 0.02 < expectedAmount) {
      return { ok: false, indeterminate: false, reason: `captured $${capAmount.toFixed(2)} < $${expectedAmount.toFixed(2)}` };
    }
    const capCustomId = (cap?.custom_id || pu?.custom_id || "").toString();
    if (capCustomId.includes("|")) {
      const [capUserId] = capCustomId.split("|");
      if (capUserId && capUserId !== userId2) {
        return { ok: false, indeterminate: false, reason: "capture belongs to a different account" };
      }
    }
    const refundResp = await fetch(`https://api-m.paypal.com/v2/payments/captures/${captureId}/refund`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
        "PayPal-Request-Id": idempotencyKey
      },
      body: JSON.stringify({})
    });
    if (refundResp.ok) {
      const rj = await refundResp.json().catch(() => ({}));
      return { ok: true, refundId: rj?.id };
    }
    const errBody = await refundResp.json().catch(() => ({}));
    const issue = (errBody?.details?.[0]?.issue || errBody?.name || "").toString();
    if (issue === "CAPTURE_FULLY_REFUNDED") return { ok: true, alreadyRefunded: true };
    const indeterminate = refundResp.status >= 500;
    return { ok: false, indeterminate, reason: `refund rejected: ${issue || refundResp.status}` };
  } catch (err) {
    return { ok: false, indeterminate: true, reason: `refund error: ${err?.message || "unknown"}` };
  }
}
async function walletFallbackCredit(userId2, amount4, description, relatedTransactionId) {
  try {
    const r = await db.transaction(
      async (tx) => refundCreditInTx(tx, userId2, amount4, description, relatedTransactionId)
    );
    return r.balanceAfter;
  } catch (err) {
    console.error("\u{1F6A8} walletFallbackCredit FAILED \u2014 manual refund needed:", userId2, amount4, err?.message);
    return null;
  }
}
async function performSourceRefund(orderId2, refundTotal, userId2, refKey, walletDescription, relatedTransactionId) {
  const rr = await refundPayPalToSource(orderId2, refundTotal, userId2, refKey);
  if (rr.ok) {
    console.log(`\u{1F4B3} PayPal source refund OK (${refKey}) refundId=${rr.refundId || "already-refunded"}`);
    return { refunded: true, refundMethod: "paypal", newBalance: null };
  }
  if (!rr.indeterminate) {
    console.warn(`\u26A0\uFE0F PayPal source refund refused (${refKey}): ${rr.reason} \u2014 falling back to wallet credit`);
    const newBalance = await walletFallbackCredit(userId2, refundTotal, walletDescription, relatedTransactionId);
    return { refunded: newBalance !== null, refundMethod: "wallet", newBalance };
  }
  console.error(`\u{1F6A8} PayPal source refund INDETERMINATE (${refKey}): ${rr.reason} \u2014 NO wallet credit issued; admin must verify in PayPal dashboard`);
  return { refunded: true, refundMethod: "paypal_pending", newBalance: null };
}
async function verifyPayPalCaptured(orderId2, expectedAmount, userId2, purpose) {
  const id2 = (orderId2 || "").trim();
  if (!id2) return { ok: false, reason: "no PayPal order reference" };
  try {
    const accessToken = await getPayPalAccessToken();
    const resp = await fetch(`https://api-m.paypal.com/v2/checkout/orders/${id2}`, {
      headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }
    });
    if (!resp.ok) return { ok: false, reason: "could not read PayPal order" };
    const od = await resp.json();
    const pu = od?.purchase_units?.[0];
    const cap = pu?.payments?.captures?.[0];
    const capStatus = cap?.status || od?.status;
    const capAmount = parseFloat(cap?.amount?.value || "0");
    const capCurrency = (cap?.amount?.currency_code || "").toUpperCase();
    if (capStatus !== "COMPLETED") return { ok: false, reason: `status ${capStatus || "?"}` };
    if (capCurrency && capCurrency !== "USD") return { ok: false, reason: `currency ${capCurrency} != USD` };
    if (capAmount + 0.02 < expectedAmount) {
      return { ok: false, reason: `captured $${capAmount.toFixed(2)} < $${expectedAmount.toFixed(2)}` };
    }
    const capCustomId = (cap?.custom_id || pu?.custom_id || "").toString();
    if (capCustomId.includes("|")) {
      const [capUserId, capPurpose] = capCustomId.split("|");
      if (capUserId && capUserId !== userId2) {
        return { ok: false, reason: "capture belongs to a different account" };
      }
      if (purpose && capPurpose && capPurpose !== purpose) {
        return { ok: false, reason: `capture purpose '${capPurpose}' != ${purpose}` };
      }
    }
    return { ok: true, capturedAmount: capAmount };
  } catch (err) {
    return { ok: false, reason: `verify error: ${err?.message || "unknown"}` };
  }
}

