async function getServiceRevenueDailySeries(serviceType, since) {
  const day = (col) => sql14`to_char(date_trunc('day', ${col}), 'YYYY-MM-DD')`;
  const bucket = (col) => sql14`date_trunc('day', ${col})`;
  let rows = [];
  switch (serviceType) {
    case "topup":
      rows = await db.select({ day: day(transactions.createdAt), revenue: sql14`COALESCE(SUM(${transactions.fee}), 0)` }).from(transactions).where(and12(eq15(transactions.type, "topup"), eq15(transactions.status, "completed"), gte6(transactions.createdAt, since))).groupBy(bucket(transactions.createdAt)).orderBy(bucket(transactions.createdAt));
      break;
    case "moncash":
      rows = await db.select({ day: day(moncashTransfers.createdAt), revenue: sql14`COALESCE(SUM(${moncashTransfers.fee}), 0) + COALESCE(SUM(${moncashTransfers.platformCashbackAmount}), 0)` }).from(moncashTransfers).where(and12(eq15(moncashTransfers.status, "completed"), gte6(moncashTransfers.createdAt, since))).groupBy(bucket(moncashTransfers.createdAt)).orderBy(bucket(moncashTransfers.createdAt));
      break;
    case "natcash":
      rows = await db.select({ day: day(natcashTransfers.createdAt), revenue: sql14`COALESCE(SUM(${natcashTransfers.fee}), 0) + COALESCE(SUM(${natcashTransfers.platformCashbackAmount}), 0)` }).from(natcashTransfers).where(and12(eq15(natcashTransfers.status, "completed"), gte6(natcashTransfers.createdAt, since))).groupBy(bucket(natcashTransfers.createdAt)).orderBy(bucket(natcashTransfers.createdAt));
      break;
    case "giftcard":
      rows = await db.select({ day: day(giftCardTransactions.createdAt), revenue: sql14`COALESCE(SUM(${giftCardTransactions.fee}), 0)` }).from(giftCardTransactions).where(and12(eq15(giftCardTransactions.status, "completed"), gte6(giftCardTransactions.createdAt, since))).groupBy(bucket(giftCardTransactions.createdAt)).orderBy(bucket(giftCardTransactions.createdAt));
      break;
    case "billpayment":
      rows = await db.select({ day: day(billTransactions.createdAt), revenue: sql14`COALESCE(SUM(${billTransactions.fee}), 0)` }).from(billTransactions).where(and12(eq15(billTransactions.status, "completed"), gte6(billTransactions.createdAt, since))).groupBy(bucket(billTransactions.createdAt)).orderBy(bucket(billTransactions.createdAt));
      break;
    case "crypto":
      rows = await db.select({ day: day(cryptoPurchaseRequests.createdAt), revenue: sql14`COALESCE(SUM(${cryptoPurchaseRequests.feeAmountUsd}), 0)` }).from(cryptoPurchaseRequests).where(and12(eq15(cryptoPurchaseRequests.status, "completed"), gte6(cryptoPurchaseRequests.createdAt, since))).groupBy(bucket(cryptoPurchaseRequests.createdAt)).orderBy(bucket(cryptoPurchaseRequests.createdAt));
      break;
    case "cashpick":
      rows = await db.select({ day: day(cashPickTransactions.createdAt), revenue: sql14`COALESCE(SUM(${cashPickTransactions.serviceFee}), 0)` }).from(cashPickTransactions).where(and12(eq15(cashPickTransactions.status, "picked_up"), gte6(cashPickTransactions.createdAt, since))).groupBy(bucket(cashPickTransactions.createdAt)).orderBy(bucket(cashPickTransactions.createdAt));
      break;
    default:
      return [];
  }
  return rows.map((r) => ({ date: r.day, revenue: parseFloat(r.revenue || "0") }));
}

