async function verifyDepositPayPalPaid(deposit) {
  const paypalOrderId2 = (deposit.paypalOrderId || "").trim();
  if (!paypalOrderId2) return { ok: false, reason: "no PayPal order reference" };
  try {
    const accessToken = await getPayPalAccessToken();
    const getResp = await fetch(`https://api-m.paypal.com/v2/checkout/orders/${paypalOrderId2}`, {
      headers: { "Authorization": `Bearer ${accessToken}`, "Content-Type": "application/json" }
    });
    if (!getResp.ok) {
      return { ok: false, reason: "could not read PayPal order" };
    }
    const od = await getResp.json();
    const pu = od?.purchase_units?.[0];
    const cap = pu?.payments?.captures?.[0];
    const capStatus = cap?.status || od?.status;
    const capAmount = parseFloat(cap?.amount?.value || "0");
    const capCurrency = (cap?.amount?.currency_code || "").toUpperCase();
    const expected = parseFloat(deposit.totalCharged || deposit.amountUsd || "0");
    if (capStatus !== "COMPLETED") {
      return { ok: false, reason: `status ${capStatus || "?"}` };
    }
    if (capCurrency && capCurrency !== "USD") {
      return { ok: false, reason: `currency ${capCurrency} != USD` };
    }
    if (capAmount + 0.02 < expected) {
      return { ok: false, reason: `captured $${capAmount.toFixed(2)} < $${expected.toFixed(2)}` };
    }
    const capCustomId = (cap?.custom_id || pu?.custom_id || "").toString();
    if (!capCustomId.includes("|")) {
      return { ok: false, reason: "PayPal capture is not bound to an account and service" };
    }
    const [capUserId, capPurpose] = capCustomId.split("|");
    if (!capUserId || capUserId !== deposit.userId) {
      return { ok: false, reason: "capture belongs to a different account" };
    }
    if (capPurpose !== "deposit") {
      return { ok: false, reason: `capture purpose '${capPurpose || "missing"}' != deposit` };
    }
    const { enforceThreeDSecureLiability: enforceThreeDSecureLiability2 } = await Promise.resolve().then(() => (init_threeDSecureGate(), threeDSecureGate_exports));
    const cardGate = await enforceThreeDSecureLiability2(paypalOrderId2, od, {
      userId: deposit.userId
    });
    if (cardGate.blocked) {
      return { ok: false, reason: `card verification failed (AVS=${cardGate.avsCode || "missing"}, 3DS=${cardGate.liabilityShift || "missing"})` };
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, reason: `verify error: ${err?.message || "unknown"}` };
  }
}
