// server/trading/market.ts
var BASE2 = { BTCUSDT: 65e3, ETHUSDT: 3500 };
async function market(symbol) {
  const now = Date.now();
  const bucket = Math.floor(now / 3e5);
  const priceAt = (n) => BASE2[symbol] * (1 + Math.sin(n / 7 + (symbol === "BTCUSDT" ? 0 : 1.7)) * 0.025);
  const candles = Array.from({ length: 96 }, (_, index2) => {
    const n = bucket - 95 + index2;
    const open = priceAt(n - 1);
    const close = priceAt(n);
    return { time: n * 300, open, close, high: Math.max(open, close) * 1.002, low: Math.min(open, close) * 0.998 };
  });
  return {
    symbol,
    price: priceAt(bucket).toFixed(2),
    source: "Synthetic Simulator",
    updatedAt: new Date(now).toISOString(),
    candles
  };
}

