function sanitizeGmailAddress(email) {
  const lower = email.toLowerCase().trim();
  const atIndex = lower.indexOf("@");
  if (atIndex === -1) return lower;
  const localPart = lower.substring(0, atIndex);
  const domain = lower.substring(atIndex + 1);
  const gmailDomains = ["gmail.com", "googlemail.com"];
  if (!gmailDomains.includes(domain)) {
    return lower;
  }
  const plusIndex = localPart.indexOf("+");
  const cleanLocal = plusIndex !== -1 ? localPart.substring(0, plusIndex) : localPart;
  const noDots = cleanLocal.replace(/\./g, "");
  return `${noDots}@gmail.com`;
}
function isDisposableEmail(email) {
  const lower = email.toLowerCase().trim();
  const atIndex = lower.indexOf("@");
  if (atIndex === -1) return false;
  const domain = lower.substring(atIndex + 1);
  if (DISPOSABLE_EMAIL_DOMAINS.has(domain)) return true;
  const parts = domain.split(".");
  for (let i = 0; i < parts.length - 1; i++) {
    const sub = parts.slice(i).join(".");
    if (DISPOSABLE_EMAIL_DOMAINS.has(sub)) return true;
  }
  return false;
}
function validateAndSanitizeEmail(email) {
  if (!email || typeof email !== "string") {
    return { valid: false, sanitizedEmail: "", reason: "Email address is required.", errorCode: "EMAIL_REQUIRED" };
  }
  const trimmed = email.trim().toLowerCase();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(trimmed)) {
    return { valid: false, sanitizedEmail: trimmed, reason: "Invalid email address format.", errorCode: "EMAIL_INVALID_FORMAT" };
  }
  if (isDisposableEmail(trimmed)) {
    return {
      valid: false,
      sanitizedEmail: trimmed,
      reason: "Temporary or disposable email addresses are not allowed. Please use a real email address.",
      errorCode: "EMAIL_DISPOSABLE"
    };
  }
  const sanitizedEmail = sanitizeGmailAddress(trimmed);
  return { valid: true, sanitizedEmail };
}

