// server/reloadly.ts
var RELOADLY_API_BASE = "https://topups.reloadly.com";
var RELOADLY_AUTH_BASE = "https://auth.reloadly.com";
var cachedAccessToken = null;
var tokenExpiryTime = 0;
async function getAccessToken() {
  if (cachedAccessToken && Date.now() < tokenExpiryTime) {
    return cachedAccessToken;
  }
  const { RELOADLY_CLIENT_ID, RELOADLY_CLIENT_SECRET } = process.env;
  if (!RELOADLY_CLIENT_ID || !RELOADLY_CLIENT_SECRET) {
    throw new Error("Missing Reloadly credentials");
  }
  try {
    const response = await fetch(`${RELOADLY_AUTH_BASE}/oauth/token`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify({
        client_id: RELOADLY_CLIENT_ID,
        client_secret: RELOADLY_CLIENT_SECRET,
        grant_type: "client_credentials",
        audience: "https://topups.reloadly.com"
      })
    });
    if (!response.ok) {
      throw new Error(`Auth failed: ${response.status}`);
    }
    const authData = await response.json();
    cachedAccessToken = authData.access_token;
    tokenExpiryTime = Date.now() + (authData.expires_in - 300) * 1e3;
    console.log("\u2705 Reloadly access token obtained");
    return authData.access_token;
  } catch (error) {
    console.error("\u274C Reloadly auth failed:", error);
    throw error;
  }
}
