import { createHmac, randomBytes as randomBytes2, randomUUID as randomUUID11 } from "node:crypto";
var BASE4 = "https://sandboxapi.rapyd.net";
function rapydSignature(method, path6, salt, timestamp2, access, secret, body) {
  const hex = createHmac("sha256", secret).update(method.toLowerCase() + path6 + salt + timestamp2 + access + secret + body).digest("hex");
  return Buffer.from(hex).toString("base64");
}
async function sandboxRequest(method, path6, payload) {
  const access = process.env.RAPYD_SANDBOX_ACCESS_KEY;
  const secret = process.env.RAPYD_SANDBOX_SECRET_KEY;
  if (!access || !secret) throw new Error("RAPYD_SANDBOX_NOT_CONFIGURED");
  if (!/^\/v1\/(?:checkout(?:\/checkout_[a-zA-Z0-9]+)?|payment_methods\/country\?country=US)$/.test(path6)) {
    throw new Error("INVALID_SANDBOX_PATH");
  }
  const body = payload === void 0 ? "" : JSON.stringify(payload);
  const salt = randomBytes2(8).toString("hex");
  const timestamp2 = Math.floor(Date.now() / 1e3).toString();
  const response = await fetch(BASE4 + path6, {
    method,
    redirect: "error",
    signal: AbortSignal.timeout(2e4),
    headers: {
      "Content-Type": "application/json",
      access_key: access,
      salt,
      timestamp: timestamp2,
      signature: rapydSignature(method, path6, salt, timestamp2, access, secret, body),
      ...method === "POST" ? { idempotency: randomUUID11() } : {}
    },
    ...body ? { body } : {}
  });
  const result = await response.json();
  if (!response.ok || result.status?.status !== "SUCCESS") {
    const code = String(result.status?.error_code || `HTTP_${response.status}`).replace(/[^A-Z0-9_]/gi, "").slice(0, 100);
    throw new Error(`RAPYD_SANDBOX_${code}`);
  }
  return result.data;
}
