// server/utils/masking.ts
function maskPhone(phone) {
  if (!phone) return "";
  const cleaned = phone.replace(/[^\d+]/g, "");
  const lastTwo = cleaned.slice(-2);
  const countryCode = cleaned.match(/^\+\d{1,3}/)?.[0] || "";
  return `${countryCode} ***-***-${lastTwo}`;
}
function maskEmail(email) {
  if (!email) return "";
  const parts = email.split("@");
  if (parts.length !== 2) return "***@***.***";
  const [username, domain] = parts;
  const domainParts = domain.split(".");
  if (domainParts.length < 2) return `${username[0]}***@***.***`;
  const maskedUsername = username[0] + "***";
  const maskedDomain = domainParts[0][0] + "***." + domainParts[domainParts.length - 1];
  return `${maskedUsername}@${maskedDomain}`;
}
function maskAccountNumber(accountNumber) {
  if (!accountNumber) return "";
  const cleaned = accountNumber.replace(/[^\d]/g, "");
  const lastFour = cleaned.slice(-4);
  return `****${lastFour}`;
}

