// server/services/sms-command-parser.ts
function parseSMSCommand(message, senderNumber) {
  const normalizedMessage = message.trim().toUpperCase();
  const parts = normalizedMessage.split(/\s+/);
  const command = parts[0];
  if (["TOPUP", "RECHARGE", "TOP", "RECHAJ"].includes(command)) {
    if (parts.length >= 3) {
      const phoneNumber = parts[1];
      const amountPart = parts[2];
      let amount4;
      let currency2 = "USD";
      if (amountPart.toUpperCase().includes("USD")) {
        amount4 = parseFloat(amountPart.replace(/USD/gi, ""));
        currency2 = "USD";
      } else if (amountPart.toUpperCase().includes("HTG")) {
        amount4 = parseFloat(amountPart.replace(/HTG/gi, ""));
        currency2 = "HTG";
      } else {
        amount4 = parseFloat(amountPart);
        currency2 = "USD";
      }
      if (isValidHaitiNumber(phoneNumber) && !isNaN(amount4) && amount4 > 0) {
        return {
          type: "topup",
          phoneNumber: formatHaitiNumber(phoneNumber),
          amount: amount4,
          currency: currency2,
          originalMessage: message,
          senderNumber
        };
      }
    }
    return {
      type: "invalid",
      originalMessage: message,
      senderNumber
    };
  }
  if (["BALANCE", "BAL", "BALANS"].includes(command)) {
    return {
      type: "balance",
      originalMessage: message,
      senderNumber
    };
  }
  if (["HISTORY", "HIST", "ISTWA"].includes(command)) {
    return {
      type: "history",
      originalMessage: message,
      senderNumber
    };
  }
  if (["HELP", "AIDE", "EDIMIWA"].includes(command)) {
    return {
      type: "help",
      originalMessage: message,
      senderNumber
    };
  }
  return {
    type: "invalid",
    originalMessage: message,
    senderNumber
  };
}
