  app2.post("/api/auth/change-password", async (req, res) => {
    try {
      const { currentPassword, newPassword } = req.body;
      if (!currentPassword || !newPassword) {
        return res.status(400).json({
          message: "Current password and new password are required"
        });
      }
      if (newPassword.length < 8) {
        return res.status(400).json({
          message: "New password must be at least 8 characters long"
        });
      }
      let userId2;
      if (req.session?.userId) {
        userId2 = req.session.userId;
        console.log(`\u{1F504} Password change for session user ${userId2}`);
      } else if (req.verifiedUser?.id || req.verifiedUser?.uid) {
        userId2 = req.verifiedUser.id || req.verifiedUser.uid;
        console.log(`\u{1F504} Password change for Firebase user ${userId2}`);
      } else {
        return res.status(401).json({ message: "Not authenticated" });
      }
      const user = await storage.getUser(userId2);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }
      const bcrypt3 = await import("bcryptjs");
      const isCurrentPasswordValid = await bcrypt3.compare(currentPassword, user.password);
      if (!isCurrentPasswordValid) {
        console.log(`\u274C Current password incorrect for user ${userId2}`);
        return res.status(401).json({
          message: "Current password is incorrect"
        });
      }
      const hashedPassword = await bcrypt3.hash(newPassword, 10);
      await storage.updateUser(userId2, { password: hashedPassword });
      console.log(`\u2705 Password updated successfully for user ${userId2}`);
      res.json({ message: "Password updated successfully" });
    } catch (error) {
      console.error("Error changing password:", error);
      res.status(500).json({
        message: "Failed to change password"
      });
    }
  });
