  app2.post("/api/admin/wallet/debit", verifyFirebaseAuth, async (req, res) => {
    try {
      const adminUser = req.user;
      const admin3 = await storage.getUser(adminUser.uid);
      if (!admin3?.isOwner && !admin3?.isSuperAdmin) {
        return res.status(403).json({ error: "Owner access required" });
      }
      const { userId: userId2, amount: amount4, reason } = req.body;
      if (!userId2 || !amount4 || !reason) {
        return res.status(400).json({ error: "userId, amount, and reason are required" });
      }
      const debitAmount = parseFloat(amount4);
      if (isNaN(debitAmount) || debitAmount <= 0 || debitAmount > 1e4) {
        return res.status(400).json({ error: "Invalid amount" });
      }
      const user = await storage.getUser(userId2);
      if (!user) return res.status(404).json({ error: "User not found" });
      const currentBal = parseFloat(user.balance || "0");
      if (currentBal < debitAmount) {
        return res.status(400).json({
          error: `Insufficient balance. Current: $${currentBal.toFixed(2)}, Requested debit: $${debitAmount.toFixed(2)}`
        });
      }
      const newBal = currentBal - debitAmount;
      const investorCredits = parseFloat(user.investorCredits || "0");
      const adminCredits = parseFloat(user.adminCredits || "0");
      const otherCredits = parseFloat(user.otherCredits || "0");
      const total = investorCredits + adminCredits + otherCredits || 1;
      const ratio = debitAmount / total;
      const newInvestor = Math.max(0, investorCredits - investorCredits * ratio);
      const newAdmin = Math.max(0, adminCredits - adminCredits * ratio);
      const newOther = Math.max(0, otherCredits - otherCredits * ratio);
      await storage.updateUser(userId2, {
        balance: newBal.toFixed(2),
        investorCredits: newInvestor.toFixed(2),
        adminCredits: newAdmin.toFixed(2),
        otherCredits: newOther.toFixed(2)
      });
      const tx = await storage.createWalletTransaction({
        userId: userId2,
        type: "debit",
        amount: debitAmount.toFixed(2),
        creditType: "other",
        balanceBefore: currentBal.toFixed(6),
        balanceAfter: newBal.toFixed(6),
        description: `Admin wallet correction (debit $${debitAmount.toFixed(2)}): ${reason}`,
        status: "completed"
      });
      console.log(`\u2705 ADMIN WALLET DEBIT: $${debitAmount} debited from ${userId2} by ${admin3.email}. New balance: $${newBal.toFixed(2)}`);
      res.json({
        success: true,
        previousBalance: currentBal.toFixed(2),
        newBalance: newBal.toFixed(2),
        debited: debitAmount.toFixed(2),
        transaction: tx
      });
    } catch (error) {
      console.error("\u274C Admin wallet debit error:", error);
      res.status(500).json({ error: error.message });
    }
  });
