  app2.post("/api/auth/verify-email", async (req, res) => {
    try {
      const { email, verificationCode } = req.body;
      if (!email || !verificationCode) {
        return res.status(400).json({ message: "Email and verification code required" });
      }
      const user = await storage.getUserByEmail(email);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }
      if (!user.emailVerificationCode || user.emailVerificationCode !== verificationCode || !user.emailVerificationExpires || /* @__PURE__ */ new Date() > user.emailVerificationExpires) {
        return res.status(400).json({ message: "Invalid or expired verification code" });
      }
      await storage.updateUser(user.id, {
        emailVerified: true,
        emailVerificationCode: null,
        emailVerificationExpires: null
      });
      console.log(`\u2705 Email verified for user ${user.email}`);
      res.json({ success: true, message: "Email verified successfully" });
    } catch (error) {
      console.error("\u274C Email verification error:", error);
      res.status(500).json({
        message: "Email verification failed"
      });
    }
  });
  app2.post("/api/auth/resend-verification", async (req, res) => {
    try {
      const { email } = req.body;
      if (!email) {
        return res.status(400).json({ message: "Email required" });
      }
      const user = await storage.getUserByEmail(email);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }
      if (user.emailVerified) {
        return res.status(400).json({ message: "Email already verified" });
      }
      const emailResult = await sendEmailVerification(email, user.firstName || "User", user.language || "en");
      if (emailResult) {
        await storage.updateUser(user.id, {
          emailVerificationCode: emailResult.code,
          emailVerificationExpires: new Date(Date.now() + 24 * 60 * 60 * 1e3)
        });
        console.log(`\u{1F4E7} Email verification resent to ${email}`);
        res.json({
          success: true,
          message: "Verification email sent successfully. Please check your email."
        });
      } else {
        res.status(500).json({
          message: "Failed to send verification email"
        });
      }
    } catch (error) {
      console.error("\u274C Resend verification error:", error);
      res.status(500).json({
        message: "Failed to resend verification"
      });
    }
  });
