  app2.get("/api/user-country", async (req, res) => {
    const isPrivateIp = (ip) => {
      const clean = ip.replace(/^::ffff:/, "").trim();
      return clean === "127.0.0.1" || clean === "::1" || clean === "0.0.0.0" || clean === "localhost" || clean === "" || clean.startsWith("192.168.") || clean.startsWith("172.16.") || clean.startsWith("172.17.") || clean.startsWith("172.18.") || clean.startsWith("172.19.") || clean.startsWith("172.20.") || clean.startsWith("172.21.") || clean.startsWith("172.22.") || clean.startsWith("172.23.") || clean.startsWith("172.24.") || clean.startsWith("172.25.") || clean.startsWith("172.26.") || clean.startsWith("172.27.") || clean.startsWith("172.28.") || clean.startsWith("172.29.") || clean.startsWith("172.30.") || clean.startsWith("172.31.") || clean.startsWith("10.");
    };
    const getRealIp = () => {
      const cfIp = req.headers["cf-connecting-ip"];
      if (cfIp && typeof cfIp === "string" && !isPrivateIp(cfIp.trim())) return cfIp.trim();
      const realIp = req.headers["x-real-ip"];
      if (realIp && typeof realIp === "string" && !isPrivateIp(realIp.trim())) return realIp.trim();
      const forwarded = req.headers["x-forwarded-for"];
      if (forwarded) {
        const chain = (typeof forwarded === "string" ? forwarded : forwarded[0]).split(",").map((s) => s.replace(/^::ffff:/, "").trim());
        const publicIp = chain.find((ip) => ip && !isPrivateIp(ip));
        if (publicIp) return publicIp;
      }
      return (req.ip || "0.0.0.0").replace(/^::ffff:/, "").trim();
    };
    try {
      const ip = getRealIp();
      if (isPrivateIp(ip)) {
        console.log(`\u{1F30D} /api/user-country: private/local IP=${ip} \u2192 treating as dev (US)`);
        return res.json({ countryCode: "US", isInternational: false });
      }
      let countryCode = null;
      try {
        const geoRes = await fetch(`https://api.country.is/${ip}`, { signal: AbortSignal.timeout(3e3) });
        const geoData = await geoRes.json();
        if (geoData.country && geoData.country.length === 2) countryCode = geoData.country;
      } catch {
        console.warn(`\u26A0\uFE0F /api/user-country: primary geo API failed for IP=${ip}`);
      }
      if (!countryCode) {
        try {
          const fbRes = await fetch(`https://ipapi.co/${ip}/country/`, { signal: AbortSignal.timeout(3e3) });
          const fbText = (await fbRes.text()).trim();
          if (fbText && fbText.length === 2 && /^[A-Z]{2}$/.test(fbText)) countryCode = fbText;
        } catch {
          console.warn(`\u26A0\uFE0F /api/user-country: fallback geo API also failed for IP=${ip}`);
        }
      }
      const finalCode = countryCode || "XX";
      const isInternational = finalCode !== "US" && finalCode !== "XX";
      console.log(`\u{1F30D} /api/user-country: IP=${ip} \u2192 Country=${finalCode} | international=${isInternational}`);
      res.json({ countryCode: finalCode, isInternational });
    } catch (err) {
      console.warn("\u26A0\uFE0F /api/user-country: Unexpected error, defaulting to unknown");
      res.json({ countryCode: "XX", isInternational: false });
    }
  });
