  app2.get("/api/admin/fcm/diagnostics", requireEmailVerification, async (req, res) => {
    try {
      if (!req.verifiedUser?.isAdmin) {
        return res.status(403).json({ error: "ADMIN_REQUIRED" });
      }
      const admin3 = await import("firebase-admin");
      const allTokens = await storage.getAllActiveDeviceTokens();
      const results = [];
      for (const dt of allTokens) {
        const token = dt.token;
        if (token.startsWith("fallback_sw_")) {
          results.push({ tokenPreview: token.substring(0, 25) + "...", userId: dt.userId, type: "fallback", error: "Fallback token \u2014 not a real FCM token", code: "FALLBACK" });
          continue;
        }
        try {
          const message = {
            notification: { title: "BuyFast Diagnostic", body: "FCM test" },
            token
          };
          await admin3.default.messaging().send(message, true);
          results.push({ tokenPreview: token.substring(0, 25) + "...", userId: dt.userId, type: "real", status: "valid", error: null, code: null });
        } catch (err) {
          const code = err.errorInfo?.code || err.code || "UNKNOWN";
          const msg = err.errorInfo?.message || err.message || "unknown error";
          results.push({ tokenPreview: token.substring(0, 25) + "...", userId: dt.userId, type: "real", status: "failed", error: msg, code });
        }
      }
      const valid = results.filter((r) => r.status === "valid").length;
      const failed = results.filter((r) => r.status === "failed").length;
      const fallback = results.filter((r) => r.type === "fallback").length;
      console.log(`\u{1F52C} FCM Diagnostics: ${valid} valid, ${failed} failed, ${fallback} fallback tokens`);
      res.json({ totalTokens: allTokens.length, valid, failed, fallback, tokens: results });
    } catch (error) {
      console.error("\u274C FCM diagnostics error:", error);
      res.status(500).json({ error: "DIAGNOSTICS_FAILED", message: error.message });
    }
  });
