  app2.post("/api/admin/chat/conversation/:id/reply", requireEmailVerification, async (req, res) => {
    try {
      if (!req.verifiedUser?.isAdmin) {
        return res.status(403).json({
          success: false,
          message: "Admin access required"
        });
      }
      const conversationId = req.params.id;
      const adminId = req.verifiedUser.id;
      const { message, attachment } = req.body;
      const allowedImageMimes = ["image/png", "image/jpeg", "image/jpg", "image/webp", "image/gif"];
      const dataUrlRegex = /^data:image\/(png|jpe?g|webp|gif);base64,[A-Za-z0-9+/=]+$/;
      const hasAttachment = !!(attachment && typeof attachment.dataUrl === "string" && dataUrlRegex.test(attachment.dataUrl) && (!attachment.type || allowedImageMimes.includes(attachment.type)));
      const trimmedMessage = (message || "").trim();
      if (!trimmedMessage && !hasAttachment) {
        return res.status(400).json({
          success: false,
          message: "Message or attachment is required"
        });
      }
      if (hasAttachment && attachment.dataUrl.length > 65e5) {
        return res.status(413).json({
          success: false,
          message: "Attachment too large. Max 5MB."
        });
      }
      const conversation = await storage.getChatConversation(conversationId);
      if (!conversation) {
        return res.status(404).json({
          success: false,
          message: "Conversation not found"
        });
      }
      if (!conversation.assignedAdminId) {
        await storage.assignChatToAdmin(conversationId, adminId);
      }
      const userLang2 = conversation.language || "en";
      const originalAdminMessage = trimmedMessage;
      let finalAdminMessage = originalAdminMessage;
      let wasTranslated = false;
      if (userLang2 !== "en" && originalAdminMessage) {
        try {
          const translated = await translateForUserLang(originalAdminMessage, userLang2);
          if (translated && translated !== originalAdminMessage) {
            finalAdminMessage = translated;
            wasTranslated = true;
            console.log(`\u{1F310} Admin reply translated to ${userLang2}: "${originalAdminMessage}" \u2192 "${translated}"`);
          }
        } catch (translateError) {
          console.warn("\u26A0\uFE0F Admin reply translation failed, sending original:", translateError);
        }
      }
      const attachmentMeta = hasAttachment ? { attachment: { type: attachment.type || "image", dataUrl: attachment.dataUrl, name: attachment.name || null } } : {};
      const translationMeta = wasTranslated ? { originalMessage: originalAdminMessage, translatedTo: userLang2, autoTranslated: true } : {};
      const combinedMeta = { ...attachmentMeta, ...translationMeta };
      const adminMessage = await storage.createChatMessage({
        conversationId,
        senderType: "admin",
        senderId: adminId,
        message: finalAdminMessage || "\u{1F4F7} Photo",
        isAutomated: false,
        metadata: Object.keys(combinedMeta).length > 0 ? combinedMeta : void 0
      });
      await storage.updateChatConversation(conversationId, {
        status: "active"
      });
      res.json({
        success: true,
        message: adminMessage
      });
    } catch (error) {
      console.error("\u274C Admin reply failed:", error);
      res.status(500).json({
        success: false,
        message: "Failed to send reply",
        error: error.message
      });
    }
  });
