  app2.get("/api/admin/scan-operators-validity", requireEmailVerification, async (req, res) => {
    try {
      if (!req.verifiedUser?.isAdmin) {
        return res.status(403).json({ message: "Admin access required" });
      }
      console.log("\u{1F50D} Starting operator validity scan...");
      const countries2 = await reloadlyService.getCountries();
      const operatorsWithValidity = [];
      const operatorsWithoutValidity = [];
      let totalOperators = 0;
      const countriesToScan = countries2.slice(0, 20);
      for (const country of countriesToScan) {
        try {
          const operators2 = await reloadlyService.getOperatorsByCountry(country.isoName);
          for (const operator2 of operators2) {
            totalOperators++;
            try {
              const details = await reloadlyService.getOperatorDetails(operator2.operatorId);
              const descriptions = details.localFixedAmountsDescriptions || details.fixedAmountsDescriptions || {};
              let hasValidity = false;
              for (const desc19 of Object.values(descriptions)) {
                const descStr = String(desc19);
                if (/\d+\s*(?:day|days|jour|jours|jou|mois|mwa|week|semaine|month)/i.test(descStr) || /valid/i.test(descStr) || /validit[ée]/i.test(descStr)) {
                  hasValidity = true;
                  break;
                }
              }
              const operatorInfo = {
                operatorId: operator2.operatorId,
                name: operator2.name,
                country: country.name,
                countryCode: country.isoName,
                hasDescriptions: Object.keys(descriptions).length > 0,
                descriptionsCount: Object.keys(descriptions).length,
                sampleDescriptions: Object.values(descriptions).slice(0, 2)
              };
              if (hasValidity) {
                operatorsWithValidity.push(operatorInfo);
              } else if (Object.keys(descriptions).length > 0) {
                operatorsWithoutValidity.push(operatorInfo);
              }
            } catch (err) {
              console.log(`\u26A0\uFE0F Error checking operator ${operator2.operatorId}:`, err);
            }
          }
        } catch (err) {
          console.log(`\u26A0\uFE0F Error fetching operators for ${country.name}:`, err);
        }
      }
      console.log(`\u2705 Scan complete: ${totalOperators} operators checked`);
      console.log(`\u2705 Found ${operatorsWithValidity.length} operators WITH validity`);
      console.log(`\u{1F4CB} Found ${operatorsWithoutValidity.length} operators with descriptions but NO validity`);
      res.json({
        summary: {
          totalScanned: totalOperators,
          withValidity: operatorsWithValidity.length,
          withDescriptionsNoValidity: operatorsWithoutValidity.length,
          countriesScanned: countriesToScan.length
        },
        operatorsWithValidity,
        operatorsWithoutValidity: operatorsWithoutValidity.slice(0, 10)
        // Sample
      });
    } catch (error) {
      console.error("\u274C Operator validity scan failed:", error);
      res.status(500).json({
        message: "Scan failed",
        error: error.message
      });
    }
  });
